package main

import "sort"

type Entry struct { Set []int; Count int64 }
type Candidates struct { Joined,Excluded,Pruned int; Sets [][]int }
func generateCandidates(previous []Entry,size int,taxonomy map[int]int,exclude bool) Candidates {
 r:=Candidates{};known:=map[string]bool{};for _,e:=range previous {known[setKey(e.Set)]=true}
 for i,a:=range previous {for _,b:=range previous[i+1:] {
  if compareSets(a.Set[:size-2],b.Set[:size-2])!=0 {break};set:=append(append([]int(nil),a.Set...),b.Set[len(b.Set)-1]);r.Joined++
  if exclude&&size==2 {first,ok:=taxonomy[set[0]];second,other:=taxonomy[set[1]];if ok&&first==set[1]||other&&second==set[0] {r.Excluded++;continue}}
  pruned:=false;for j:=range set {part:=append(append([]int(nil),set[:j]...),set[j+1:]...);if !known[setKey(part)] {pruned=true;break}};if pruned {r.Pruned++} else {r.Sets=append(r.Sets,set)}
 }}
 sort.Slice(r.Sets,func(i,j int)bool{return compareSets(r.Sets[i],r.Sets[j])<0});return r
}
func countCandidates(support *Support,sets [][]int,minimum int64) []Entry {var entries []Entry;for _,set:=range sets {count:=support.count(set);if count>=minimum {entries=append(entries,Entry{set,count})}};return entries}

package main

import (
 "os"
 "sort"
 "strconv"
 "strings"
)

type Product struct { Name,Category string; Price int64 }
type Basket struct { ID,Customer string; Day int; Counts map[int]int64 }
func readLines(name string) []string {data,e:=os.ReadFile("input/"+name);if e!=nil {panic(e)};return strings.Split(strings.TrimSuffix(string(data),"\n"),"\n")}
func records(name string) [][]string {var rows [][]string;for _,line:=range readLines(name)[1:] {rows=append(rows,strings.Split(line,","))};return rows}
func parseInt(s string) int64 {v,e:=strconv.ParseInt(s,10,64);if e!=nil {panic(e)};return v}
func (b *Basket) items(taxonomy map[int]int,extended bool) []int {found:=map[int]bool{};for i:=range b.Counts {found[i]=true;if extended {found[taxonomy[i]]=true}};var ids []int;for i:=range found {ids=append(ids,i)};sort.Ints(ids);return ids}
func contains(items []bool,set []int) bool {for _,i:=range set {if !items[i] {return false}};return true}
func itemSets(baskets []*Basket,taxonomy map[int]int,extended bool,width int) [][]bool {sets:=make([][]bool,len(baskets));for j,b:=range baskets {set:=make([]bool,width);for _,i:=range b.items(taxonomy,extended) {set[i]=true};sets[j]=set};return sets}
func setKey(set []int) string {parts:=make([]string,len(set));for j,i:=range set {parts[j]=strconv.Itoa(i)};return strings.Join(parts,",")}
func compareSets(a,b []int) int {for j:=0;j<min(len(a),len(b));j++ {if a[j]<b[j] {return -1};if a[j]>b[j] {return 1}};if len(a)<len(b) {return -1};if len(a)>len(b) {return 1};return 0}
func subset(a,b []int) bool {j:=0;for _,i:=range b {if j<len(a)&&a[j]==i {j++}};return j==len(a)}
func union(a,b []int) []int {all:=append(append([]int(nil),a...),b...);sort.Ints(all);var out []int;for _,i:=range all {if len(out)==0||out[len(out)-1]!=i {out=append(out,i)}};return out}
func selected(set []int,mask int) []int {var out []int;for j,i:=range set {if mask&(1<<j)!=0 {out=append(out,i)}};return out}
type Support struct { Sets [][]bool; Cache map[string]int64 }
func newSupport(sets [][]bool) *Support {return &Support{sets,map[string]int64{"":int64(len(sets))}}}
func (s *Support) count(set []int) int64 {key:=setKey(set);if count,ok:=s.Cache[key];ok {return count};var count int64;for _,b:=range s.Sets {if contains(b,set) {count++}};s.Cache[key]=count;return count}

package main

import "sort"

type Pattern struct { Items []int; Weight int64 }
type FPNode struct { Item int; Count int64; Parent *FPNode; Children map[int]*FPNode }
type FPTree struct { Header []int; Root *FPNode; Links map[int][]*FPNode; Nodes int }
type Growth struct { Header,Nodes,Trees,ConditionalNodes int; Entries []Entry }
func buildTree(base []Pattern,minimum int64) *FPTree {
 supports:=map[int]int64{};for _,p:=range base {for _,i:=range p.Items {supports[i]+=p.Weight}}
 tree:=&FPTree{Root:&FPNode{Item:-1,Children:map[int]*FPNode{}},Links:map[int][]*FPNode{}}
 for i,count:=range supports {if count>=minimum {tree.Header=append(tree.Header,i)}};sort.Slice(tree.Header,func(a,b int)bool{x,y:=tree.Header[a],tree.Header[b];if supports[x]!=supports[y] {return supports[x]>supports[y]};return x<y});order:=map[int]int{};for j,i:=range tree.Header {order[i]=j}
 for _,p:=range base {var path []int;for _,i:=range p.Items {if _,ok:=order[i];ok {path=append(path,i)}};sort.Slice(path,func(i,j int)bool{return order[path[i]]<order[path[j]]});node:=tree.Root
  for _,i:=range path {child:=node.Children[i];if child==nil {child=&FPNode{Item:i,Parent:node,Children:map[int]*FPNode{}};node.Children[i]=child;tree.Links[i]=append(tree.Links[i],child);tree.Nodes++};child.Count+=p.Weight;node=child}
 };return tree
}
func (t *FPTree) conditional(item int) []Pattern {var base []Pattern;for _,node:=range t.Links[item] {var path []int;for ancestor:=node.Parent;ancestor!=t.Root;ancestor=ancestor.Parent {path=append(path,ancestor.Item)};for i,j:=0,len(path)-1;i<j;i,j=i+1,j-1 {path[i],path[j]=path[j],path[i]};base=append(base,Pattern{path,node.Count})};return base}
func fpGrowth(baskets []*Basket,taxonomy map[int]int,minimum int64,maxSize int) Growth {
 var base []Pattern;for _,b:=range baskets {base=append(base,Pattern{b.items(taxonomy,false),1})};tree:=buildTree(base,minimum);r:=Growth{Header:len(tree.Header),Nodes:tree.Nodes}
 type Frame struct {Tree *FPTree;Suffix []int};stack:=[]Frame{{tree,nil}}
 for len(stack)>0 {frame:=stack[len(stack)-1];stack=stack[:len(stack)-1];for j:=len(frame.Tree.Header)-1;j>=0;j-- {item:=frame.Tree.Header[j];set:=union(frame.Suffix,[]int{item});var count int64;for _,node:=range frame.Tree.Links[item] {count+=node.Count};r.Entries=append(r.Entries,Entry{set,count});if len(set)<maxSize {conditional:=buildTree(frame.Tree.conditional(item),minimum);if conditional.Nodes>0 {stack=append(stack,Frame{conditional,set});r.Trees++;r.ConditionalNodes+=conditional.Nodes}}}}
 sort.Slice(r.Entries,func(i,j int)bool{a,b:=r.Entries[i],r.Entries[j];if len(a.Set)!=len(b.Set) {return len(a.Set)<len(b.Set)};return compareSets(a.Set,b.Set)<0});return r
}

package main

import (
 "fmt"
 "sort"
 "strings"
)

type Params struct { Minimum,CategoryMinimum,SequenceMinimum,TrainMinimum,TestMinimum,NegativeExpected int64; MaxSize,Split,Top,Matrix int; Confidence,Lift,GroupLift,NegativeLift,Trend Fraction }
type Level struct { Size,Joined,Excluded,Pruned,Counted int; Frequent []Entry }
type Apriori struct { Levels []Level; Entries []Entry; Counts map[string]int64 }
type Evaluation struct { Cases,Covered,Hit1,Hit,Baseline int64 }
type Customer struct { ID string; Baskets []*Basket; Days map[int]bool; Purchased []bool; ProductDays map[int][]int; CategoryUnits []int64; First,Last int; Units,Revenue int64 }
type Analysis struct {
 P Params; Names []string; Products map[int]Product; ProductIDs,CategoryIDs []int; Taxonomy map[int]int
 Errors []string; ItemRows,TransactionRows,Adopted,Duplicates,Transactions,Empty int
 Baskets,Train,Test []*Basket; MainSupport,ExtendedSupport,TrainSupport,TestSupport *Support
 Frequent,Category,Training,Testing Apriori; Rules,CategoryRules,TrainRules,TestRules RuleSet; Growth Growth
 Closed,Maximal,Generators []Entry; Customers []*Customer; Buyers map[int]int64
 HeldOut,Hits,Units,Revenue map[int]int64; TotalUnits,TotalRevenue int64; First,Last int
 Evaluation map[int]*Evaluation; TotalEvaluation Evaluation; Validation []string; Emerging,Hold,Fail,Unseen int
 SequenceLines []string; SequencePairs,FrequentSequences,MultiDay int
}
func readParams() Params {fields:=map[string]string{};for _,line:=range readLines("params.txt") {p:=strings.Fields(line);fields[p[0]]=p[1]};f:=func(name string)Fraction{parts:=strings.Split(fields[name],"/");return fraction(parseInt(parts[0]),parseInt(parts[1]))};n:=func(name string)int64{return parseInt(fields[name])};return Params{n("min_support"),n("category_min_support"),n("sequence_min_support"),n("train_min_support"),n("test_min_support"),n("negative_min_expected"),int(n("max_size")),int(n("split_day")),int(n("recommend_top")),int(n("matrix_size")),f("min_confidence"),f("min_lift"),f("group_min_lift"),f("negative_max_lift"),f("trend_threshold")}}
func readAnalysis() *Analysis {
 a:=&Analysis{P:readParams(),Products:map[int]Product{},Taxonomy:map[int]int{},Buyers:map[int]int64{},HeldOut:map[int]int64{},Hits:map[int]int64{},Units:map[int]int64{},Revenue:map[int]int64{},Evaluation:map[int]*Evaluation{}}
 productByName:=map[string]Product{};categories:=map[string]bool{}
 for j,row:=range records("items.csv") {a.ItemRows++;p:=Product{row[0],row[1],parseInt(row[2])};reason:="";if _,exists:=productByName[p.Name];exists {reason="duplicate item "+p.Name} else if p.Price==0 {reason="bad price 0"};if reason!="" {a.Errors=append(a.Errors,fmt.Sprintf("items.csv line %d: %s",j+2,reason));continue};productByName[p.Name]=p;categories[p.Category]=true}
 var categoryNames,productNames []string;for name:=range categories {categoryNames=append(categoryNames,name)};for name:=range productByName {productNames=append(productNames,name)};sort.Strings(categoryNames);sort.Strings(productNames);a.Names=append(categoryNames,productNames...);index:=map[string]int{};for i,name:=range a.Names {index[name]=i;if i<len(categoryNames) {a.CategoryIDs=append(a.CategoryIDs,i)} else {a.ProductIDs=append(a.ProductIDs,i);a.Products[i]=productByName[name]}};for i,p:=range a.Products {a.Taxonomy[i]=index[p.Category]}
 transactions:=map[string]*Basket{};var ordered []*Basket;var previous *Basket
 for j,row:=range records("transactions.csv") {
  a.TransactionRows++;tid,customer,day,name:=row[0],row[1],int(parseInt(row[2])),row[3]
  existing,seen:=transactions[tid];if previous!=nil&&tid!=previous.ID&&seen {a.Errors=append(a.Errors,fmt.Sprintf("transactions.csv line %d: tid %s not contiguous",j+2,tid));continue}
  if !seen {existing=&Basket{tid,customer,day,map[int]int64{}};transactions[tid]=existing;ordered=append(ordered,existing);previous=existing;a.Transactions++}
  reason:="";if customer!=existing.Customer {reason=fmt.Sprintf("tid %s customer %s differs from %s",tid,customer,existing.Customer)} else if day!=existing.Day {reason=fmt.Sprintf("tid %s day %d differs from %d",tid,day,existing.Day)} else if _,ok:=productByName[name];!ok {reason="unknown item "+name}
  if reason!="" {a.Errors=append(a.Errors,fmt.Sprintf("transactions.csv line %d: %s",j+2,reason));continue};id:=index[name];if existing.Counts[id]>0 {a.Duplicates++};existing.Counts[id]++;a.Adopted++
 }
 for _,b:=range ordered {if len(b.Counts)==0 {a.Empty++;continue};a.Baskets=append(a.Baskets,b);if b.Day<=a.P.Split {a.Train=append(a.Train,b)} else {a.Test=append(a.Test,b)}}
 width:=len(a.Names);a.MainSupport=newSupport(itemSets(a.Baskets,a.Taxonomy,false,width));a.ExtendedSupport=newSupport(itemSets(a.Baskets,a.Taxonomy,true,width));a.TrainSupport=newSupport(itemSets(a.Train,a.Taxonomy,false,width));a.TestSupport=newSupport(itemSets(a.Test,a.Taxonomy,false,width))
 return a
}
func (a *Analysis) apriori(support *Support,universe []int,minimum int64,exclude bool) Apriori {
 result:=Apriori{Counts:map[string]int64{"":int64(len(support.Sets))}};var previous []Entry
 for size:=1;size<=a.P.MaxSize;size++ {var candidates Candidates;if size==1 {for _,i:=range universe {candidates.Sets=append(candidates.Sets,[]int{i})};candidates.Joined=len(universe)} else {if len(previous)==0 {break};candidates=generateCandidates(previous,size,a.Taxonomy,exclude)};frequent:=countCandidates(support,candidates.Sets,minimum);result.Levels=append(result.Levels,Level{size,candidates.Joined,candidates.Excluded,candidates.Pruned,len(candidates.Sets),frequent});result.Entries=append(result.Entries,frequent...);for _,e:=range frequent {result.Counts[setKey(e.Set)]=e.Count};previous=frequent}
 return result
}
func (a *Analysis) makeRules(g Apriori,total int64,category bool) RuleSet {
 result:=RuleSet{}
 for _,e:=range g.Entries {if len(e.Set)<2 {continue};if category&&e.Set[0]>=len(a.CategoryIDs) {continue};full:=(1<<len(e.Set))-1
  for mask:=1;mask<full;mask++ {result.Generated++;x,y:=selected(e.Set,mask),selected(e.Set,full^mask);r:=ruleMetrics(e.Set,x,y,e.Count,total,g.Counts[setKey(x)],g.Counts[setKey(y)]);if !thresholds(r.Confidence,r.Lift,a.P) {continue};best:=fraction(0,1);for part:=0;part<(1<<len(x))-1;part++ {w:=selected(x,part);confidence:=fraction(g.Counts[setKey(union(w,y))],g.Counts[setKey(w)]);if confidence.compare(best)>0 {best=confidence}};r.Improvement=r.Confidence.subtract(best);if r.Improvement.N>0 {result.Productive++};result.Rules=append(result.Rules,r)}
 };sort.Slice(result.Rules,func(i,j int)bool{return compareRules(result.Rules[i],result.Rules[j])<0});for i:=range result.Rules {result.Rules[i].Rank=i+1};return result
}
func (a *Analysis) classify() {
 for _,x:=range a.Frequent.Entries {closed,maximal,generator:=true,true,true;for _,y:=range a.Frequent.Entries {if len(y.Set)>len(x.Set)&&subset(x.Set,y.Set) {maximal=false;if x.Count==y.Count {closed=false}}};for j:=range x.Set {part:=append(append([]int(nil),x.Set[:j]...),x.Set[j+1:]...);if a.Frequent.Counts[setKey(part)]<=x.Count {generator=false;break}};if closed {a.Closed=append(a.Closed,x)};if maximal {a.Maximal=append(a.Maximal,x)};if generator {a.Generators=append(a.Generators,x)}}
}
func (a *Analysis) buildCustomers() {
 found:=map[string]*Customer{};a.First=113
 for _,b:=range a.Baskets {
  c:=found[b.Customer];if c==nil {c=&Customer{ID:b.Customer,Days:map[int]bool{},Purchased:make([]bool,len(a.Names)),ProductDays:map[int][]int{},CategoryUnits:make([]int64,len(a.CategoryIDs)),First:113};found[b.Customer]=c};c.Baskets=append(c.Baskets,b);c.Days[b.Day]=true;c.First=min(c.First,b.Day);c.Last=max(c.Last,b.Day);a.First=min(a.First,b.Day);a.Last=max(a.Last,b.Day)
  for i,units:=range b.Counts {p:=a.Products[i];c.Purchased[i]=true;c.ProductDays[i]=append(c.ProductDays[i],b.Day);c.CategoryUnits[a.Taxonomy[i]]+=units;c.Units+=units;c.Revenue+=units*p.Price;a.Units[i]+=units;a.Revenue[i]+=units*p.Price;a.TotalUnits+=units;a.TotalRevenue+=units*p.Price}
 }
 var ids []string;for id:=range found {ids=append(ids,id)};sort.Strings(ids)
 for _,id:=range ids {c:=found[id];if len(c.Days)>=2 {a.MultiDay++};for i,days:=range c.ProductDays {sort.Ints(days);var unique []int;for _,d:=range days {if len(unique)==0||unique[len(unique)-1]!=d {unique=append(unique,d)}};c.ProductDays[i]=unique;a.Buyers[i]++};a.Customers=append(a.Customers,c)}
}
func median(values []int) Fraction {sort.Ints(values);n:=len(values);if n%2==1 {return fraction(int64(values[n/2]),1)};return fraction(int64(values[n/2-1]+values[n/2]),2)}
func minimumGap(first,second []int) int {best,j:=113,0;for _,x:=range first {for j<len(second)&&second[j]<=x {j++};if j<len(second) {best=min(best,second[j]-x)}};return best}
func (a *Analysis) sequences() {
 type Sequence struct {A,B int;Count int64;Confidence,Lift,Gap Fraction};var seqs []Sequence
 type Repeat struct {Item,Customers int;Intervals []int;Mean,Median Fraction};var repeats []Repeat
 for _,i:=range a.ProductIDs {for _,j:=range a.ProductIDs {var gaps []int;for _,c:=range a.Customers {x,y:=c.ProductDays[i],c.ProductDays[j];if len(x)>0&&len(y)>0&&x[0]<y[len(y)-1] {gaps=append(gaps,minimumGap(x,y))}};q:=int64(len(gaps));if q>0 {a.SequencePairs++};if q>=a.P.SequenceMinimum {seqs=append(seqs,Sequence{i,j,q,fraction(q,a.Buyers[i]),fraction(q*int64(len(a.Customers)),a.Buyers[i]*a.Buyers[j]),median(gaps)})}}
  rep:=Repeat{Item:i};var total int64;for _,c:=range a.Customers {days:=c.ProductDays[i];if len(days)<2 {continue};rep.Customers++;for k:=1;k<len(days);k++ {d:=days[k]-days[k-1];rep.Intervals=append(rep.Intervals,d);total+=int64(d)}};if len(rep.Intervals)>0 {rep.Mean=fraction(total,int64(len(rep.Intervals)));rep.Median=median(rep.Intervals);repeats=append(repeats,rep)}
 }
 sort.Slice(seqs,func(i,j int)bool{x,y:=seqs[i],seqs[j];if x.Count!=y.Count {return x.Count>y.Count};if c:=x.Confidence.compare(y.Confidence);c!=0 {return c>0};if x.A!=y.A {return x.A<y.A};return x.B<y.B});a.FrequentSequences=len(seqs)
 for rank,s:=range seqs {a.SequenceLines=append(a.SequenceLines,fmt.Sprintf("SEQ %d %s -> %s customers %d base %d confidence %s lift %s gap %s",rank+1,a.Names[s.A],a.Names[s.B],s.Count,a.Buyers[s.A],fractionText(s.Confidence),fractionText(s.Lift),fractionText(s.Gap)))}
 sort.Slice(repeats,func(i,j int)bool{x,y:=repeats[i],repeats[j];if c:=x.Mean.compare(y.Mean);c!=0 {return c<0};return x.Item<y.Item});for _,r:=range repeats {a.SequenceLines=append(a.SequenceLines,fmt.Sprintf("REPEAT %s customers %d intervals %d min %d max %d mean %s median %s",a.Names[r.Item],r.Customers,len(r.Intervals),r.Intervals[0],r.Intervals[len(r.Intervals)-1],fractionText(r.Mean),fractionText(r.Median)))}
}
func recommendations(held []bool,candidates []int,top int) []int {selected:=map[int]bool{};var out []int;for _,i:=range candidates {if held[i]||selected[i] {continue};selected[i]=true;out=append(out,i);if len(out)==top {break}};return out}
func ruleCandidates(rules []Rule,held []bool) []int {var candidates []int;for _,r:=range rules {if len(r.Y)==1&&contains(held,r.X) {candidates=append(candidates,r.Y[0])}};return candidates}
func (a *Analysis) popular(support *Support,ids []int) []int {order:=append([]int(nil),ids...);sort.Slice(order,func(i,j int)bool{x,y:=support.count([]int{order[i]}),support.count([]int{order[j]});if x!=y {return x>y};return order[i]<order[j]});return order}
func hasID(ids []int,id int) bool {for _,i:=range ids {if i==id {return true}};return false}
func addEvaluation(a *Evaluation,b Evaluation) {a.Cases+=b.Cases;a.Covered+=b.Covered;a.Hit1+=b.Hit1;a.Hit+=b.Hit;a.Baseline+=b.Baseline}
func evaluationText(e Evaluation) string {return fmt.Sprintf("cases %d covered %d hit1 %d hit %d rate %s baseline %d rate %s",e.Cases,e.Covered,e.Hit1,e.Hit,fractionText(fraction(e.Hit,e.Cases)),e.Baseline,fractionText(fraction(e.Baseline,e.Cases)))}
func (a *Analysis) validate() {
 training:=map[string]bool{};for _,r:=range a.TrainRules.Rules {training[setKey(r.X)+"->"+setKey(r.Y)]=true;nx,ny,nz:=a.TestSupport.count(r.X),a.TestSupport.count(r.Y),a.TestSupport.count(r.Set);confidence,liftText,verdict:="-","-","UNSEEN";if nx==0||ny==0 {a.Unseen++} else {conf,lr:=fraction(nz,nx),lift(int64(len(a.Test)),nz,nx,ny);confidence,liftText=fractionText(conf),fractionText(lr);if thresholds(conf,lr,a.P) {verdict="HOLD";a.Hold++} else {verdict="FAIL";a.Fail++}};a.Validation=append(a.Validation,fmt.Sprintf("RULE %d %s train %d confidence %s lift %s test %d of %d confidence %s lift %s %s",r.Rank,arrow(r,a.Names),r.Count,fractionText(r.Confidence),fractionText(r.Lift),nz,nx,confidence,liftText,verdict))}
 for _,r:=range a.TestRules.Rules {if !training[setKey(r.X)+"->"+setKey(r.Y)] {a.Emerging++;a.Validation=append(a.Validation,fmt.Sprintf("EMERGING %d %s test %d confidence %s lift %s",r.Rank,arrow(r,a.Names),r.Count,fractionText(r.Confidence),fractionText(r.Lift)))}}
 a.Validation=append(a.Validation,fmt.Sprintf("VALIDATION train %d test %d itemsets %d rules %d hold %d fail %d unseen %d emerging %d",len(a.Train),len(a.Test),len(a.Training.Entries),len(a.TrainRules.Rules),a.Hold,a.Fail,a.Unseen,a.Emerging))
 popular:=a.popular(a.TrainSupport,a.ProductIDs)
 for _,b:=range a.Test {size:=len(b.Counts);if size<2 {continue};for _,h:=range b.items(a.Taxonomy,false) {held:=make([]bool,len(a.Names));for i:=range b.Counts {held[i]=i!=h};rec:=recommendations(held,ruleCandidates(a.TrainRules.Rules,held),a.P.Top);baseline:=recommendations(held,popular,a.P.Top);e:=Evaluation{Cases:1};a.HeldOut[h]++;if len(rec)>0 {e.Covered=1;if rec[0]==h {e.Hit1=1}};if hasID(rec,h) {e.Hit=1;a.Hits[h]++};if hasID(baseline,h) {e.Baseline=1};if a.Evaluation[size]==nil {a.Evaluation[size]=&Evaluation{}};addEvaluation(a.Evaluation[size],e);addEvaluation(&a.TotalEvaluation,e)}}
 var sizes []int;for size:=range a.Evaluation {sizes=append(sizes,size)};sort.Ints(sizes);for _,size:=range sizes {a.Validation=append(a.Validation,fmt.Sprintf("RECOMMEND size %d %s",size,evaluationText(*a.Evaluation[size])))};a.Validation=append(a.Validation,"RECOMMEND total "+evaluationText(a.TotalEvaluation))
}
func (a *Analysis) summaryLines() []string {
 var lines []string;for _,e:=range a.Errors {lines=append(lines,"ERROR "+e)};sizes:=map[int]int64{};var sum int64;largest:=0;for _,b:=range a.Baskets {size:=len(b.Counts);sizes[size]++;sum+=int64(size);largest=max(largest,size)}
